import{_ as e,o as c,c as d,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"Cookie","description":"","frontmatter":{"title":"Cookie","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Web基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第四部分：Web 基础/03-Cookie 与 Session/Cookie.md","filePath":"posts/java快速入门/第四部分：Web 基础/03-Cookie 与 Session/Cookie.md"}'),t={name:"posts/java快速入门/第四部分：Web 基础/03-Cookie 与 Session/Cookie.md"};function p(s,o,a,l,k,n){return c(),d("div",null,[...o[0]||(o[0]=[i('<div><p><strong>会话技术</strong>   <code>1.</code> 会话：一次会话中包含多次请求和响应。      <code>*</code> 一次会话：浏览器第一次给服务器资源发送请求，会话建立，直到有一方断开为止   <code>2.</code> 功能：在一次会话的范围内的多次请求间，共享数据   <code>3.</code> 方式：      <code>1.</code> 客户端会话技术：</p><ul><li>Cookie</li><li><ol start="2"><li></li></ol></li></ul><p>服务器端会话技术：<code>Session</code></p><p><code>Cookie</code><strong>：</strong> 概念：客户端会话技术，将数据保存到客户端</p><p><strong>快速入门：</strong>    <code>*</code> 使用步骤：    <code>1.</code> 创建<code>Cookie</code>对象，绑定数据</p><ul><li><ul><li>new Cookie(String name, String value)</li></ul></li><li><ol start="2"><li></li></ol></li></ul><p>发送<code>Cookie</code>对象</p><p><code>* response.addCookie(Cookie cookie)</code></p><p><code>3.</code> 获取<code>Cookie</code>，拿到数据       <code>* Cookie[] request.getCookies()</code></p><p><strong>实现原理</strong>    <code>*</code> 基于响应头<code>set-cookie</code>和请求头<code>cookie</code>实现</p><p><code>cookie</code><strong>的细节</strong><code>1.</code> 一次可不可以发送多个</p><ul><li>cookie?</li><li><ul><li></li></ul></li></ul><p>可以 <code>*</code> 可以创建多个<code>Cookie</code>对象，然后多次调用<code>response</code>.<code>addCookie</code>方法发送<code>cookie</code>即可。</p><p><code>2. cookie</code>在浏览器中保存多长时间？ <code>1.</code> 默认情况下，当浏览器关闭后，<code>Cookie</code>数据被销毁 <code>2.</code> 持久化存储： <code>* setMaxAge(int seconds)</code></p><p><code>1.</code> 正数：将<code>Cookie</code>数据写到硬盘的文件中。持久化存储。并指定<code>cookie</code>存活时间，时间到后，<code>cookie</code>文件自动失效 <code>2.</code> 负数：默认值，浏览器关闭后销毁<code>Cookie</code>； <code>3.</code> 零：删除<code>cookie</code>信息</p><p><code>3. cookie</code></p><p>能不能存中文？    <code>*</code> 在<code>tomcat 8</code> 之前 <code>cookie</code>中不能直接存储中文数据。    <code>*</code> 需要将中文数据转码<code>---</code>一般采用<code>URL</code>编码</p><p><code>(%E3)</code></p><p>，即用<code>%</code>加两个<code>16</code>进制数字表示一个字节。    <code>*</code> 在<code>tomcat 8</code> 之后，<code>cookie</code>支持中文数据。特殊字符还是不支持，建议使用<code>URL</code>编码存储，<code>URL</code>解码解析。</p><p><code>4. cookie</code></p><p>共享问题？    <code>1.</code> 假设在一个<code>tomcat</code>服务器中，部署了多个<code>web</code>项目，那么在这些<code>web</code>项目中<code>cookie</code>能不能共享？     <code>*</code> 默认情况下<code>cookie</code>不能共享     <code>* setPath(String path)</code>：设置<code>cookie</code>的获取范围。默认情况下，设置当前的虚拟目录     <code>*</code> 如果要共享，则可以将<code>path</code>设置为<code>&quot;/&quot;</code></p><p><code>2.</code></p><p>不同的<code>tomcat</code>服务器间<code>cookie</code>共享问题？     <code>* setDomain(String path)</code>：如果设置一级域名相同，那么多个服务器之间<code>cookie</code>可以共享     <code>* setDomain(&quot;.baidu.com&quot;)</code>，那么<code>tieba.baidu.com</code>和<code>news.baidu.com</code>中<code>cookie</code>可以共享</p><p><code>5. Cookie</code></p><p>的特点和作用   <code>1. cookie</code>存储数据在客户端浏览器   <code>2.</code> 浏览器对于单个<code>cookie</code> 的大小有限制<code>(4kb)</code> 以及 对同一个域名下的总<code>cookie</code>数量也有限制<code>(20</code>个</p><ul><li>)</li><li><ul><li></li></ul></li></ul><p>作用：     <code>1. cookie</code>一般用于存出少量的不太敏感的数据     <code>2.</code> 在不登录的情况下，完成服务器对客户端的身份识别</p></div>',1)])])}const C=e(t,[["render",p]]);export{u as __pageData,C as default};
